/*
 * Pro tips
 * - Invariant: the stack is the fully reduced version of the processed prefix.
 * - If the next character matches the top, pop one pair; otherwise push it.
 * - Pairs cancel, not entire runs: bbb leaves b. New pairs can form across a removed pair.
 * - push stores characters in reverse order; removeLast restores left-to-right output.
 * - Check cascading removals, odd-length runs, and complete cancellation. O(n) time and O(n) space.
 */

import java.lang.StringBuilder;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

class Solution {
    public static String removeAdjacentDuplicatesInString(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (!stack.isEmpty() && stack.peek() == c) {
                stack.pop();
            } else {
                stack.push(c);
            }
        }

        StringBuilder result = new StringBuilder();
        while (!stack.isEmpty()) {
            result.append(stack.removeLast());
        }
        return result.toString();
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
        String res = removeAdjacentDuplicatesInString(s);
        System.out.println(res);
    }
}
